nswer":{"answers":["نصف تفاحة"]}},{"lessonId":"7c46654c-2243-4d7e-9a86-2a67f177a4fe","lessonTitle":"ورقة عمل (37) الجزء والكل","page":69,"section":"practice","activity_order":6,"activity_type":"matching","title":"أربط الكلمة بالتعريف","prompt":"صل الكلمات ومعانيها الصحيحة في نشاط «ورقة عمل (37) الجزء والكل».","content":{"origin":"DADYOOM_BH_G1_FIVE_SPATIAL_HEALTH_MATH_WORKBOOKS_25_20261030","anchor":"تفاحة كاملة، نصف تفاحة، قطعة.","grade":1,"originalReference":"ضاديوم — إثراء أصلي للصف الأول في البحرين، «ورقة عمل (37) الجزء والكل». يتعلم الطفل معنى تفاحة كاملة، نصف تفاحة، قطعة عبر الأمثلة الجديدة الآتية: «تفاحة كاملة» تعني تفاحة لم تُقسم إلى أجزاء؛ «نصف تفاحة» تعني أحد جزأين متساويين من التفاحة؛ «قطعة» تعني جزء مفصول من شيء أكبر. ينطق المعلم الأمثلة ثم يمنح الطفل فرصة للتمثيل أو الإشارة أو القراءة بمساعدة مناسبة. بعد الإجابة، يقارن الطفل اختياره بالدليل ويفسر اختياره بجملة أو إشارة. نحن لا ننقل نص الكتاب الوزاري، ولم نتحقق بعد من التطابق التفصيلي مع طبعة العام الدراسي الرسمية؛ هذا تدريب مستقل من إعداد ضاديوم.","left":["تفاحة كاملة","نصف تفاحة","قطعة"],"right":["جزء مفصول من شيء أكبر","أحد جزأين متساويين من التفاحة","تفاحة لم تُقسم إلى أجزاء"]},"answer":{"pairs":[{"left":"تفاحة كاملة","right":"تفاحة لم تُقسم إلى أجزاء"},{"left":"نصف تفاحة","right":"أحد جزأين متساويين من التفاحة"},{"left":"قطعة","right":"جزء مفصول من شيء أكبر"}]}}]$life$::jsonb)
AS x("lessonId" text,"lessonTitle" text,page int,activity_order int,activity_type text,title text,section text,prompt text,content jsonb,answer jsonb);
DO $check$ DECLARE eligible integer; inserted integer;
BEGIN
 IF (SELECT count(*) FROM pg_temp.g1_five_life_25)<>25
 OR (SELECT count(DISTINCT lesson_id) FROM pg_temp.g1_five_life_25)<>5
 OR (SELECT count(DISTINCT (lesson_id,activity_order)) FROM pg_temp.g1_five_life_25)<>25
 OR EXISTS(SELECT 1 FROM pg_temp.g1_five_life_25 x WHERE
 x.activity_order NOT BETWEEN 2 AND 6 OR length(x.content->>'originalReference')<300
 OR x.content ? 'answer' OR x.content ? 'correct'
 OR (x.activity_type='multiple_choice' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(x.content->'options') v WHERE v=x.answer->>'correct'))
 OR (x.activity_type='fill_blank' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(x.content->'items'->0->'options') v WHERE v=x.answer->'answers'->>0))
 OR (x.activity_type='matching' AND jsonb_array_length(x.answer->'pairs')<>jsonb_array_length(x.content->'left')))
 THEN RAISE EXCEPTION 'Incorrect Grade1 life worksheet content'; END IF;
 SELECT count(DISTINCT l.id) INTO eligible FROM public.lessons l
 JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 JOIN public.curricula cu ON cu.id=g.curriculum_id JOIN public.countries co ON co.id=cu.country_id
 JOIN pg_temp.g1_five_life_25 x ON x.lesson_id=l.id AND x.lesson_title=l.title AND x.page=l.source_page_start
 WHERE l.status='published' AND g.grade_number=1 AND co.code='BH'
 AND l.source_pdf_url IS NOT NULL AND position(x.content->>'anchor' IN l.content)>0
 AND (SELECT count(*) FROM public.lesson_activities a WHERE a.lesson_id=l.id AND a.is_published)=1
 AND (SELECT max(activity_order) FROM public.lesson_activities a WHERE a.lesson_id=l.id)=1
 AND NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts t JOIN public.lesson_activities a ON a.id=t.activity_id WHERE a.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.question_attempts t JOIN public.questions q ON q.id=t.question_id WHERE q.lesson_id=l.id);
 IF eligible<>5 THEN RAISE EXCEPTION 'Original lesson source or prior history drift: % / 5',eligible; END IF;
 IF EXISTS(SELECT 1 FROM public.lesson_activities a WHERE a.content->>'origin'='DADYOOM_BH_G1_FIVE_SPATIAL_HEALTH_MATH_WORKBOOKS_25_20261030') THEN RAISE EXCEPTION 'Previously run batch'; END IF;
 INSERT INTO public.lesson_activities(lesson_id,title,activity_type,instructions,content,activity_order,points,is_published,section,prompt,answer,is_required)
 SELECT x.lesson_id,x.title,x.activity_type,'أنشطة إثرائية من تأليف ضاديوم؛ الاستعانة بالمعلم عند الحاجة.',x.content,x.activity_order,5,true,x.section,x.prompt,x.answer,false FROM pg_temp.g1_five_life_25 x;
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>25 THEN RAISE EXCEPTION 'Rollback: expected 25 got %',inserted; END IF;
END $check$;
COMMIT;